package com.dhegeniusmedia.sms;
import java.io.OutputStream;import java.net.HttpURLConnection;import java.net.URL;import java.nio.charset.StandardCharsets;
public final class MainActivityPost{private static final String BASE="https://dhe-genius-media.onrender.com";public static boolean post(String path,String token,String json){try{HttpURLConnection x=(HttpURLConnection)new URL(BASE+path).openConnection();x.setRequestMethod("POST");x.setRequestProperty("Authorization","Bearer "+token);x.setRequestProperty("Content-Type","application/json");x.setConnectTimeout(15000);x.setReadTimeout(15000);x.setDoOutput(true);try(OutputStream os=x.getOutputStream()){os.write(json.getBytes(StandardCharsets.UTF_8));}int code=x.getResponseCode();x.disconnect();return code>=200&&code<300;}catch(Exception e){return false;}}}